package dev.shadw.olympia.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.resources.ResourceLocation;

/** Renders the Satyr with its own model and texture. Generated by shadw-mod mob. */
public class SatyrRenderer extends MobRenderer<Satyr, LivingEntityRenderState, SatyrModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("olympia", "textures/entity/satyr.png");

	public SatyrRenderer(EntityRendererProvider.Context context) {
		super(context, new SatyrModel(context.bakeLayer(SatyrModel.LAYER)), 0.5F);
	}

	@Override
	public LivingEntityRenderState createRenderState() {
		return new LivingEntityRenderState();
	}

	@Override
	public ResourceLocation getTextureLocation(LivingEntityRenderState state) {
		return TEXTURE;
	}
}
